import javax.swing.*;import java.awt.*;
@SuppressWarnings({"unchecked","rawtypes"}) public class AllowanceSettingsPanel extends JPanel {
    private static final String[] TEMPLATE_ALLOWANCES={"HRA","Attendance Bonus"};private final JTextField[] values=new JTextField[2];private final JComboBox<String>[] types=new JComboBox[2];private final JLabel[] helpers=new JLabel[2];
    @SuppressWarnings("unchecked") public AllowanceSettingsPanel(){setLayout(new GridBagLayout());GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(5,7,5,7);c.fill=GridBagConstraints.HORIZONTAL;c.gridx=0;c.gridy=0;c.gridwidth=4;JLabel note=new JLabel("All allowance values entered below are monthly defaults.");note.setForeground(new Color(70,70,70));note.setBorder(BorderFactory.createEmptyBorder(0,0,3,0));add(note,c);c.gridwidth=1;for(int i=0;i<TEMPLATE_ALLOWANCES.length;i++){String name=TEMPLATE_ALLOWANCES[i];c.gridx=0;c.gridy=i+1;add(new JLabel(name),c);values[i]=new JTextField(Money.text(CompanyPolicyStore.allowance(name)),12);c.gridx=1;add(values[i],c);types[i]=new JComboBox<>(new String[]{"Fixed (₹)","% of Basic Pay"});types[i].setSelectedIndex(CompanyPolicyStore.percentage(name)?1:0);helpers[i]=new JLabel();updateHelper(i);final int row=i;types[i].addActionListener(e->updateHelper(row));c.gridx=2;add(types[i],c);c.gridx=3;add(helpers[i],c);}JButton save=new JButton("Save Allowance Defaults");save.addActionListener(e->save());c.gridx=1;c.gridy=3;c.gridwidth=2;add(save,c);}
    private void updateHelper(int i){helpers[i].setText(types[i].getSelectedIndex()==1?"(% of Monthly Prorated Basic Pay)":"(Fixed Amount)");}
    private void save(){try{for(int i=0;i<values.length;i++){String name=TEMPLATE_ALLOWANCES[i];CompanyPolicyStore.allowance(name,Double.parseDouble(values[i].getText()));CompanyPolicyStore.percentage(name,types[i].getSelectedIndex()==1);}ActivityLogger.log("CTC Settings","ALLOWANCE DEFAULTS SAVED","Allowance templates updated for new CTC records only","UPDATE");JOptionPane.showMessageDialog(this,"Allowance defaults saved. Existing employee CTC records were not changed.");}catch(NumberFormatException e){JOptionPane.showMessageDialog(this,"Enter valid numeric allowance values.");}}
    private double value(String name,Employee employee){double configured=CompanyPolicyStore.allowance(name);return CompanyPolicyStore.percentage(name)?configured*employee.getBasicSalary()/100:configured;}
}
